#define RPM 30.0
#define ANGULAR_VELOCITY (RPM * 2.0 * M_PI / 60.0)  /* rad/s */

DEFINE_GRID_MOTION(disc_rotation, domain, dt, time, dtime)
{
    Thread *tf = DT_THREAD(domain);
    Node *node;
    real x, y, z;
    real center_x = 0.0, center_y = 0.0;  /* Set to your disc center coords */
    real distance, theta;

    begin_node_loop(node, tf)
