        x = NODE_X(node);
        y = NODE_Y(node);
        z = NODE_Z(node);

        /* Calculate distance from rotation center */
        distance = sqrt((x - center_x)*(x - center_x) + 
                       (y - center_y)*(y - center_y));

        /* Only apply motion to nodes near disc (within tolerance) */
        if (distance <= DISC_RADIUS * 1.1)
        {
            /* Tangential velocity: v = ω × r */
            theta = atan2(y - center_y, x - center_x);

            NODE_X(node) += ANGULAR_VELOCITY * distance * cos(theta + ANGULAR_VELOCITY*dtime) * dtime;
            NODE_Y(node) += ANGULAR_VELOCITY * distance * sin(theta + ANGULAR_VELOCITY*dtime) * dtime;
        }
    }
    end_node_loop(node, tf)
}

